const item = $input.first().json;
const out = item.output;

// Skip when the agent returned insufficient_data
if (!out || out.status !== 'evaluation_completed' || !out.ratingBreakdown) {
  return [{ json: item }];
}

const rb = out.ratingBreakdown;

// Same field names as the agent output
const keys = ['technicalKnowledge','practicalKnowledge','realTimeExposure',
              'crossQuestionHandling','communication','confidence','problemSolving'];

// Read and validate scores (whole numbers 1-5)
const s = {};
for (const k of keys) {
  const v = Number(typeof rb[k] === 'object' && rb[k] !== null ? rb[k].score : rb[k]);
  if (!Number.isFinite(v) || v < 1 || v > 5) {
    throw new Error(`Invalid or missing score for ${k}: ${JSON.stringify(rb[k])}`);
  }
  s[k] = Math.round(v);
}

// Fixed business weights
const W = {
  technicalKnowledge: 0.20,
  practicalKnowledge: 0.40,
  realTimeExposure: 0.10,
  crossQuestionHandling: 0.15,
  communication: 0.05,
  confidence: 0.05,
  problemSolving: 0.05
};

let raw = 0;
for (const k of keys) raw += s[k] * W[k];

// Snap to the nearest 0.25 first, then apply caps (caps land on the band below)
let r = Math.round(raw * 4) / 4;
const applied = [];

function cap(max, why) { if (r > max) { r = max; applied.push(why); } }

// Gate 1: weak practical / project / cross-question => below 3.00
if (s.practicalKnowledge <= 2 || s.realTimeExposure <= 2 || s.crossQuestionHandling <= 2)
  cap(2.75, 'practical/project/cross-question <= 2');

// Gate 2: all three only "3" => limited to 3.25
if (s.practicalKnowledge === 3 && s.crossQuestionHandling === 3)
  cap(3.25, 'practical = 3 and cross-question = 3');

// Gate 3: 3.00+ needs all of these
if (r >= 3.0 && !(s.practicalKnowledge >= 3 && s.realTimeExposure >= 3 &&
                  s.crossQuestionHandling >= 3 && s.problemSolving >= 3))
  cap(2.75, '3.0+ requirements not met');

// Gate 4: critical gaps => below 2.00
if (s.technicalKnowledge === 1 || s.communication === 1 || s.realTimeExposure === 1)
  cap(1.75, 'critical gap (technical/communication/project = 1)');

// Gate 5: above 4.00 needs strong practical and cross-question
if (r > 4.0 && (s.practicalKnowledge < 4 || s.crossQuestionHandling < 4))
  cap(3.5, '>4.0 needs practical >= 4 and cross-question >= 4');
if (r >= 4.5 && s.practicalKnowledge < 5)
  cap(4.25, '>=4.5 needs practical = 5');

r = Math.min(5, Math.max(1, r));

// Keep the agent's own number for comparison, then overwrite
const agentRating = out.candidateEvaluationSummary?.overallRating ?? null;
out.candidateEvaluationSummary = out.candidateEvaluationSummary || {};
out.candidateEvaluationSummary.overallRating = r;
if (out.overallRating !== undefined) out.overallRating = r;

// Debug info (remove if your parser/next node is strict)
item.ratingMeta = { rawWeightedScore: Number(raw.toFixed(2)), finalRating: r, agentRating, capsApplied: applied };

return [{ json: item }];
